sources.base:
def summarize(values):
    total = sum(values)
    return {"count": len(values), "total_ms": total}

sources.C1:
def summarize(values):
    total = sum(values)
    count = len(values)
    return {"count": count, "total_ms": total, "mean_ms": total / count if count else None}

